package net.civeira.phylax.feature.observe.observedissue.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.observe.observedissue.domain.ObservedIssue;
import net.civeira.phylax.feature.observe.observedissue.domain.valueobject.AssigneeNameVO;

class AssigneeNameValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of assignee name of observed issue")
  void test_assignee_name_value_holder_assign_plain_value() {
    Object holder = new Object();
    AssigneeNameValueHolder<Object> value = new AssigneeNameValueHolder<>(holder);
    Assertions.assertSame(holder, value.assigneeName("one"), "Setters must return the holder");
    Assertions.assertTrue(value.getAssigneeNameValue().isPresent(),
        "The plain value must be stored");
    Assertions.assertEquals("one", value.getAssigneeName().orElse(null),
        "The plain value must be recovered");
    Assertions.assertSame(holder, value.assigneeNameNull(), "Setters must return the holder");
    Assertions.assertTrue(value.getAssigneeNameValue().isPresent(),
        "A null value object must be stored");
    Assertions.assertFalse(value.getAssigneeName().isPresent(),
        "A null value must not have content");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of assignee name of observed issue")
  void test_assignee_name_value_holder_assign_value_object() {
    Object holder = new Object();
    AssigneeNameValueHolder<Object> value = new AssigneeNameValueHolder<>(holder);
    AssigneeNameVO vo = AssigneeNameVO.from("one");
    Assertions.assertFalse(value.getAssigneeNameValue().isPresent(), "A new holder must be empty");
    Assertions.assertSame(holder, value.assigneeName(vo), "Setters must return the holder");
    Assertions.assertSame(vo, value.getAssigneeNameValue().orElseThrow());
    Assertions.assertSame(holder, value.assigneeName(Optional.empty()));
    Assertions.assertFalse(value.getAssigneeNameValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.assigneeName(Optional.of(vo)));
    Assertions.assertSame(vo, value.getAssigneeNameValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of assignee name of observed issue against the original")
  void test_assignee_name_value_holder_read() {
    Object holder = new Object();
    AssigneeNameValueHolder<Object> value = new AssigneeNameValueHolder<>(holder);
    AssigneeNameVO vo = AssigneeNameVO.from("one");
    AssigneeNameVO other = AssigneeNameVO.from("one");
    ObservedIssue original = Mockito.mock(ObservedIssue.class);
    Mockito.when(original.getAssigneeNameValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readAssigneeName(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNotNull(value.readAssigneeName(Optional.empty(), fails),
        "Without value and original a null value is returned");
    Assertions.assertTrue(fails.isEmpty(), "An optional value is never reported as missing");
    value.assigneeName(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readAssigneeName(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readAssigneeName(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of assignee name of observed issue")
  void test_assignee_name_value_holder_unset() {
    Object holder = new Object();
    AssigneeNameValueHolder<Object> value = new AssigneeNameValueHolder<>(holder);
    AssigneeNameVO vo = AssigneeNameVO.from("one");
    value.assigneeName(vo);
    Assertions.assertSame(holder, value.unsetAssigneeNameIfMatches("assigneeName_other"));
    Assertions.assertTrue(value.getAssigneeNameValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder, value.unsetAssigneeNameIfMatches("assigneeName"));
    Assertions.assertFalse(value.getAssigneeNameValue().isPresent(),
        "The field name must clear the value");
    value.assigneeName(vo);
    Assertions.assertSame(holder, value.unsetAssigneeName());
    Assertions.assertFalse(value.getAssigneeNameValue().isPresent(), "Unset must clear the value");
  }
}
